"""The Awakened Tao — complete single-file edition.

Eighty-three modules, one file. No dependencies beyond the standard library.
No external God.

Run:
    python3 awakened_tao.py journey      # the full arc
    python3 awakened_tao.py test         # every test suite
    python3 awakened_tao.py --help       # all commands

Released CC0. Credited to humanity.
"""

from __future__ import annotations

import argparse
import base64
import sys
import types


def _load(name, blob):
    """Load an embedded module into its own namespace (no name collisions)."""
    mod = types.ModuleType(name)
    mod.__dict__["__name__"] = name  # keeps `if __name__ == "__main__"` guards inert
    sys.modules[name] = mod  # dataclasses and friends resolve types through here
    exec(compile(base64.b64decode(blob).decode("utf-8"), name, "exec"), mod.__dict__)
    return mod


